g=[[9,9,9,9,4,9,4,4,4,9,4,4,4,9,4,4,9,9,4],[9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,4],[9]*19,[9,9,9,9,4,9,4,4,4,4,9,9,4,4,4,4,4,4,4],[9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,9],[9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,4],[9,9,9,9,4,4,9,4,9,4,4,9,9,4,9,4,9,4,4]]+[[9]*19 for _ in range(3)]
# Rule likely all selected lines that have three+ seeds; what if one row has multiple? let's render these only
out=[r[:] for r in g]
for r in range(7):
 cs=[c for c,v in enumerate(g[r]) if v==4]
 if len(cs)>=3:
  for a,b in zip(cs,cs[1:]):
   for c in range(a+1,b):out[r][c]=2
for c in range(19):
 rs=[r for r in range(7) if g[r][c]==4]
 if len(rs)>=3:
  for a,b in zip(rs,rs[1:]):
   for r in range(a+1,b):out[r][c]=2
print('\n'.join(' '.join(map(str,r)) for r in out))

